import re as _re
assert len(CHAPTERS) == 20
for c in CHAPTERS:
    assert len(c["story"]) == 8, (c["n"], "story", len(c["story"]))
    assert len(c["terms"]) == 6, (c["n"], "terms", len(c["terms"]))
    assert len(c["quiz"]) == 6, (c["n"], "quiz", len(c["quiz"]))
    assert len(c["medical"]) == 2, (c["n"], "medical")
    for q, opts, ans, why in c["quiz"]:
        assert 0 <= ans < len(opts) and len(set(opts)) == len(opts), (c["n"], q)
    blob = " ".join(c["story"] + c["medical"] + [c["intro"]] + [x for t in c["terms"] for x in t] + list(c["concept"][1]) + list(c["activity"][1]))
    assert not _re.search(r"(?<!হোমিওপ্যাথিক )ডাক্তার", blob), (c["n"], "bare ডাক্তার")
